import React, { useState } from "react";
import { checkout } from "../api/api";
import ReceiptModal from "../components/ReceiptModal";
import { useNavigate } from "react-router-dom";

export default function Checkout() {
  const [form, setForm] = useState({ name: "", email: "" });
  const [receipt, setReceipt] = useState(null);
  const navigate = useNavigate();

  const handleCheckout = async () => {
    const res = await checkout(form);
    setReceipt(res.data.receipt);
  };

  return (
    <div className="container mt-4">
      <h2>Checkout</h2>
      <input className="form-control mb-2" placeholder="Name" onChange={e => setForm({ ...form, name: e.target.value })} />
      <input className="form-control mb-2" placeholder="Email" onChange={e => setForm({ ...form, email: e.target.value })} />
      <button className="btn btn-success" onClick={handleCheckout}>Get Receipt</button>

      {receipt && <ReceiptModal receipt={receipt} onClose={() => setReceipt(null)} navigateHome={() => navigate('/')} />}
    </div>
  );
}
